namespace RetroTests { static class Options { public static void Run(){UI.Toggle("chkLog",true);UI.Check(bool.Parse(UI.Attr("btnOpenLog","visible")),"open log visible");UI.Toggle("chkLog",false);UI.Toggle("chkWarn",false);UI.Toggle("chkWarn",true);UI.Toggle("chkFull",true);UI.Check(Ranorex.Host.Local.FindSingle<Ranorex.Form>(UI.Root,10000).WindowState.ToString()=="Maximized","maximized");UI.Toggle("chkFull",false);UI.Check(Ranorex.Host.Local.FindSingle<Ranorex.Form>(UI.Root,10000).WindowState.ToString()=="Normal","normal");} } }
